class GSLHistogram:
    def __init__(self, n_bins):
        self.n_bins = n_bins
        self.hist_ptr = gsl.gsl_histogram_alloc(self.n_bins)

    def set_bin_values(self, values):
        if len(values) != self.n_bins:
            raise ValueError("Number of values must match number of bins")
        for i, value in enumerate(values):
            gsl.gsl_histogram_set(self.hist_ptr, i, value)

    def reset(self):
        gsl.gsl_histogram_reset(self.hist_ptr)

    def get_bin_values(self):
        values = []
        for i in range(self.n_bins):
            values.append(gsl.gsl_histogram_get(self.hist_ptr, i))
        return values

